package com.bookstore.repository; import com.bookstore.entity.Book; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface BookRepository extends JpaRepository<Book,Long>{ List<Book> findByTitleContainingIgnoreCaseOrIsbnContainingIgnoreCase(String title,String isbn); List<Book> findByAuthorId(Long id); List<Book> findByCategoryId(Long id); }